mapper.select:
SELECT
    USER_ID AS userId
FROM users
WHERE USER_ID = #{userId}
  AND USER_PWD = #{pwd}

mapper.update:
UPDATE users
SET USER_PWD = #{newPwd}
WHERE USER_ID = #{userId}

mapper.select:
SELECT COUNT(*)
FROM pet
WHERE USER_ID = #{userId}

mapper.update:
UPDATE pet
SET
    PET_NAME = #{petName},
    SPECIES = #{species},
    BREED = #{breed},
    BIRTHDATE = #{birthdate},
    GENDER = #{gender}
WHERE USER_ID = #{userId}
  AND PET_NO = #{petNo}

mapper.delete:
DELETE FROM pet
WHERE USER_ID = #{userId}
  AND PET_NO = #{petNo}

mapper.update:
UPDATE pet
SET IS_MAIN = 'N'
WHERE USER_ID = #{userId}

UPDATE pet
SET IS_MAIN = 'Y'
WHERE USER_ID = #{userId}
  AND PET_NO = #{petNo}
